public(package) fun track_flash_loan_usage<CoinType>(
    self: &mut Referral,
    mut fee: Coin<CoinType>,
    referral_code: String,
    who: address,
    ctx: &mut TxContext
): Coin<CoinType> {
    // verify referral code exists
    assert!(self.code_owner.contains(referral_code), error::referral_invalid_referral_code());

    let initial_fee = fee.value();
    let referer = self.look_up_code_owner(referral_code);

    let referee_rebates_amount = initial_fee * self.referee_discount_bps / DENOMINATOR;
    let referee_rebates = fee.split(referee_rebates_amount, ctx).into_balance();

    let fee_remaining = initial_fee - referee_rebates_amount;

    let referrer_rebates_amount = fee_remaining * self.referrer_discount_bps / DENOMINATOR;
    let referrer_rebates = fee.split(referrer_rebates_amount, ctx).into_balance();

    // record user rebates

    self.update_user_rebate<CoinType>(who, referee_rebates);

    emit(ReferralRecordedEvent {
        coin_type: type_name::with_defining_ids<CoinType>(),
        amount: referrer_rebates.value(),
        referee: who,
        referer,
    });
    self.update_user_rebate<CoinType>(referer, referrer_rebates);

    fee
}

public(package) fun generate_referral_code(
    self: &mut Referral,
    random: &Random,
    ctx: &mut TxContext
) {
    let sender = ctx.sender();
    if (self.referrer_code.contains(sender)) {
        abort error::referral_already_has_referral_code()
    };

    // check deposit threshold
    assert!(self.is_qualified_to_create_referral_code(sender), error::referral_not_qualified_to_gen_code());

    // generate unique referral code (keep generating until we find one that doesn't exist)
    let referral_code = generate_random_string(random, REFERRAL_CODE_LENGTH, ctx);
    assert!(!self.code_owner.contains(referral_code), error::referral_invalid_referral_code());

    // Store the mapping: code -> owner and owner -> code
    self.code_owner.add(referral_code, sender);
    self.referrer_code.add( sender, referral_code);
}

